const test = require("node:test");
const assert = require("node:assert");

const { render } = require("./template");

test("plain substitution unaffected", () => {
  assert.strictEqual(render("hi {{name}}", { name: "Ada" }), "hi Ada");
});

test("truthy if-block keeps its content", () => {
  assert.strictEqual(
    render("{{#if admin}}welcome, boss{{/if}}", { admin: true }),
    "welcome, boss",
  );
});

test("falsy if-block is removed", () => {
  assert.strictEqual(render("{{#if admin}}welcome, boss{{/if}}", { admin: false }), "");
});

test("nested if-blocks both apply", () => {
  const tpl = "{{#if outer}}A{{#if inner}}B{{/if}}C{{/if}}D";
  assert.strictEqual(render(tpl, { outer: true, inner: true }), "ABCD");
  assert.strictEqual(render(tpl, { outer: true, inner: false }), "ACD");
  assert.strictEqual(render(tpl, { outer: false, inner: true }), "D");
});

test("if-block content can contain plain substitutions", () => {
  const tpl = "{{#if show}}hello {{name}}{{/if}}";
  assert.strictEqual(render(tpl, { show: true, name: "Grace" }), "hello Grace");
});

