function render(template, data) {
  // Replaces {{key}} with data[key] (String()-coerced; missing keys become
  // an empty string). Supports {{#if key}}...{{/if}} blocks: the content
  // between the tags is kept only when data[key] is truthy, and blocks may
  // be nested. Blocks are resolved BEFORE plain {{key}} substitution.
  const withBlocks = resolveIfBlocks(template, data);
  return withBlocks.replace(/\{\{(\w+)\}\}/g, (_match, key) => {
    return Object.hasOwn(data, key) ? String(data[key]) : "";
  });
}

function resolveIfBlocks(template, data) {
  let out = "";
  let i = 0;
  while (i < template.length) {
    const openMatch = /\{\{#if (\w+)\}\}/.exec(template.slice(i));
    if (!openMatch) {
      out += template.slice(i);
      break;
    }
    const openStart = i + openMatch.index;
    const openEnd = openStart + openMatch[0].length;
    out += template.slice(i, openStart);

    // Track nesting depth to find the MATCHING {{/if}} - a naive regex
    // pairs the first {{#if}} with the first {{/if}}, which is wrong as
    // soon as blocks nest.
    let depth = 1;
    const tagPattern = /\{\{#if \w+\}\}|\{\{\/if\}\}/g;
    tagPattern.lastIndex = openEnd;
    let closeStart = -1;
    let closeEnd = -1;
    let m;
    while ((m = tagPattern.exec(template)) !== null) {
      if (m[0].startsWith("{{#if")) {
        depth++;
      } else {
        depth--;
        if (depth === 0) {
          closeStart = m.index;
          closeEnd = m.index + m[0].length;
          break;
        }
      }
    }
    if (closeStart === -1) {
      out += template.slice(openStart);
      break;
    }

    const key = openMatch[1];
    const inner = template.slice(openEnd, closeStart);
    if (data[key]) {
      out += resolveIfBlocks(inner, data);
    }
    i = closeEnd;
  }
  return out;
}

module.exports = { render };

